-- PRIORITY 1 — pool hydrator (perpetual; re-queues itself)
INSERT INTO task_pool (task_name, prompt, category, instance_target, priority, estimated_minutes) VALUES
('pool-hydrator', 'Keep the OVERMIND pool at >=10 waiting tasks focused on orchestrating the OTHER cannons (fortress, conduit, ledger, relay, bastion, supermax). This cannon watches and tunes the fleet; it also owns TRIGGER tasks that enqueue work into other pools or fire other cannons. Check depth: SELECT COUNT(*) FROM task_pool WHERE instance_target=''overmind'' AND status=''waiting''. If <10, generate 6 specific IMPLEMENTATION or TRIGGER tasks. Priority 20-60. Insert, re-queue yourself priority 1, log pool.hydrated.', 'meta', 'overmind', 1, 8);

-- TASK POOL (8 tasks)
INSERT INTO task_pool (task_name, prompt, category, instance_target, priority, estimated_minutes) VALUES
('fleet-dashboard', 'Build a single fleet dashboard (HTML in R2 or a worker route, auto-refresh) showing every cannon side by side: waiting/running/completed/failed counts, last fire time, chain depth today, pause state, and last 5 events per instance. Query task_pool + events + cannon_state grouped by instance_target/source. One screen = whole fleet. Document the queries.', 'dashboard', 'overmind', 20, 28),
('pool-balancer', 'Build a pool balancer: detect a starving cannon (waiting near 0 while others are deep) or a stalled one (no cannon.fired event in >20 min) and recommend/act. For starvation, it may enqueue a hydrator nudge; for a stall, it may fire the cannon (see fire-trigger task). Log every balancing action to events. Document the thresholds.', 'orchestration', 'overmind', 24, 25),
('fleet-quality-scoring', 'Score completed tasks across ALL cannons: completeness, time-vs-estimate, retry/failure rate by category and instance. Surface systemic issues (a cannon whose estimates are always low, a category that always fails). Write a weekly fleet quality report to R2 and post a summary to #cannon-ops via RELAY. Document the scoring method.', 'analytics', 'overmind', 28, 25),
('trigger-cross-pool-enqueue', 'Build the CROSS-POOL ENQUEUE trigger primitive: a task whose whole job is to INSERT tasks into ANOTHER cannon''s pool based on a condition. Example: when FORTRESS completes ''dmarc-stage3-reject'', enqueue a ''verify mail deliverability end-to-end'' task into RELAY''s pool. Implement a reusable helper: enqueue(target_instance, task) that writes to task_pool with the right instance_target. Log a ''trigger.enqueued'' event. Document how to define new cross-pool rules.', 'trigger', 'overmind', 30, 22),
('trigger-fire-cannon', 'Build the FIRE-CANNON trigger primitive: a task that calls create_scheduled_task to kick a specific cannon''s next fire IMMEDIATELY (jump the interval) instead of waiting. Use for: a starving/stalled cannon, or a dependency just cleared and downstream work should run now. Guard against firing a paused or runaway-tripped cannon. Log ''trigger.fired'' with target + reason. This is orchestration, not research — it triggers other things. Document usage and guards.', 'trigger', 'overmind', 32, 20),
('fleet-cost-throughput', 'Aggregate cost/throughput across the fleet from the events table: salvos/hour, tasks/hour, hot-streak vs cooldown ratio, per-cannon burn rate, and (if AI Gateway logging is wired) token/$ spend per cannon. Render trends. This tells you which cannon is actually producing and which is spinning. Write to the fleet dashboard and a daily digest. Document the metrics.', 'analytics', 'overmind', 34, 22),
('global-circuit-breaker', 'Implement a GLOBAL circuit breaker in cannon_state: if multiple cannons cross a failure threshold in the same window (e.g. >=5 task_failed events across the fleet in 15 min), set every <instance>_paused=''true'' and log ''fleet.circuit_open''. Auto-clear after a cooldown when failure rate drops, logging ''fleet.circuit_closed''. This stops a systemic problem (e.g. a leaked/rotated secret) from burning credits fleet-wide. Document thresholds and the manual override.', 'reliability', 'overmind', 38, 20),
('dependency-graph', 'Build a cross-cannon dependency graph using the depends_on column + cross-pool triggers: encode real ordering (FORTRESS secrets before CONDUIT wiring; CONDUIT AI Gateway before RELAY''s AI panel; LEDGER R2-system-of-record before knowledge sync). Visualize it and let OVERMIND respect it when firing/enqueuing. Document the graph and how new dependencies are added.', 'orchestration', 'overmind', 42, 22);

